def max_product(num_str, N, K):
    # Iterate through each position in the number string
    for i in range(N-1):
        # Check if the number at this position is greater than the number at the next position
        if num_str[i] > num_str[i+1]:
            # If so, swap the numbers
            num_str[i], num_str[i+1] = num_str[i+1], num_str[i]
    # Return the maximum product
    return product(num_str)

