def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D array to store the number of chatting pairs that can be separated by each aisle position
    aisle_matrix = [[0] * (M + 1) for _ in range(N + 1)]

    # Populate the aisle matrix with the number of chatting pairs that can be separated by each aisle position
    for position in chatting_pairs:
        x, y = position[0], position[1]
        for i in range(x + 1, M + 1):
            for j in range(y + 1, N + 1):
                aisle_matrix[i][j] += 1

    # Initialize variables to track the optimal row and column indices for the aisles
    row_indices, col_indices = [], []

    # Iterate through the aisle matrix and select the most effective positions for aisles
    for i in range(M + 1):
        for j in range(N + 1):
            if aisle_matrix[i][j] > 0:
                row_indices.append(i)
                col_indices.append(j)

    # Sort the row and column indices to ensure that they are in ascending order
    row_indices.sort()
    col_indices.sort()

    # Return the final optimal row and column indices for the aisles
    return " ".join(map(str, row_indices)), " ".join(map(str, col_indices))

