def max_energy(beads):
    n = len(beads)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = max(dp[i - 1], dp[i - 2] + beads[i - 1] * beads[i - 2])
    return dp[n]

