    if len(coeffs) > n:
        raise ValueError("Polynomial degree mismatch: expected n = {} but got coeffs of length {}".format(n, len(coeffs)))
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = "-" if coeff < 0 else "+"
        coeff = abs(coeff)
        if coeff == 1 and degree > 0:
            term = "x^{}".format(degree)
        elif coeff == 1 and degree == 0:
            term = "x"
        elif coeff == 1 and degree == 0:
            term = ""
        else:
            term = "{}x^{}".format(coeff, degree)
        terms.append(term)
