    def bfs(graph, start):
        queue = [start]
        visited = set()
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                for neighbour in graph[node]:
                    if neighbour not in visited:
                        queue.append(neighbour)
        return len(visited)

    graph = defaultdict(list)
    for rule in rules:
        x, y = rule
